/** Relative reference generated by storage, never a client-supplied path. */
export type PhotoReference = string;

export interface NormalizedItemPhoto {
  bytes: Uint8Array;
  format: 'webp';
}

/** Infrastructure validates actual content and enforces A09 before returning. */
export interface ItemPhotoProcessor {
  normalize(input: Uint8Array): Promise<NormalizedItemPhoto>;
}

export interface ItemPhotoStorage {
  /** Generates a new reference for this operation; stores one normalized file. */
  save(photo: NormalizedItemPhoto): Promise<PhotoReference>;
  /** Checks persisted references first. On uncertainty, keeps the file and fails. */
  removeIfUnreferenced(reference: PhotoReference): Promise<void>;
}

/** Application error: transport maps codes without depending on Sharp. */
export class PhotoProcessingError extends Error {
  constructor(public readonly code: 'SIZE' | 'INVALID' | 'FORMAT' | 'ANIMATED' | 'PIXELS' | 'BUSY') {
    super('Photo processing failed: ' + code);
  }
}
